"""Fraud detection helpers for transaction description analysis."""

from __future__ import annotations

import json
import os
import urllib.error
import urllib.request

OPENAI_API_URL = "https://api.openai.com/v1/chat/completions"
DEFAULT_OPENAI_MODEL = os.getenv("OPENAI_FRAUD_MODEL", "gpt-4o")


def is_transaction_description_suspicious(description: str) -> bool:
    """Return True if GPT judges the transaction description as suspicious.

    The OpenAI API key must be available via the OPENAI_API_KEY environment
    variable. This helper keeps the contract intentionally simple and returns
    False when the input is blank or the model response cannot be interpreted.
    """
    if not description or not description.strip():
        return False

    api_key = os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise RuntimeError("OPENAI_API_KEY environment variable is not set")

    payload = {
        "model": DEFAULT_OPENAI_MODEL,
        "temperature": 0,
        "messages": [
            {
                "role": "system",
                "content": (
                    "You are a fraud detection assistant. "
                    "Decide whether the provided transaction description looks suspicious. "
                    "Reply with only one word: true or false."
                ),
            },
            {
                "role": "user",
                "content": f"Transaction description: {description}",
            },
        ],
    }

    request = urllib.request.Request(
        OPENAI_API_URL,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        method="POST",
    )

    try:
        with urllib.request.urlopen(request, timeout=15) as response:
            body = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        error_body = exc.read().decode("utf-8", errors="ignore")
        raise RuntimeError(f"OpenAI API request failed: {exc.code} {error_body}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Unable to reach OpenAI API: {exc}") from exc

    content = (
        body.get("choices", [{}])[0]
        .get("message", {})
        .get("content", "")
        .strip()
        .lower()
    )

    if content == "true":
        return True
    if content == "false":
        return False

    return "true" in content and "false" not in content
